<?php
require_once __DIR__.'/../core/JalaliDate.php';
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/HrModule.php';require_once __DIR__.'/../services/TestScoringService.php';Auth::requirePermission('hr_assessments.results');$pageTitle='نتایج آزمون‌های سازمانی';$user=Auth::user();$ids=HrModule::accessibleEmployeeIds($user);if(!$ids)$ids=[-1];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){http_response_code(419);exit('درخواست نامعتبر است.');}if(!Auth::isAdmin()&&!Auth::can('hr_assessments.recalculate')){http_response_code(403);exit('دسترسی غیرمجاز است.');}$result=Database::fetch('SELECT * FROM hr_assessment_results WHERE id=?',[(int)$_POST['result_id']]);if(!$result||!in_array((int)$result['employee_id'],$ids,true)){http_response_code(404);exit('رکورد موردنظر یافت نشد.');}try{$new=(new TestScoringService())->calculate($result['employee_id'],$result['test_id'],$result['raw_answers_json'],$result['assignment_id']);Database::execute('INSERT INTO hr_assessment_result_logs(result_id,action,performed_by,old_value_json,new_value_json,created_at) VALUES (?,"recalculate",?,?,?,NOW())',[$new['result_id'],(int)$user['id'],json_encode(['result_id'=>$result['id']],JSON_UNESCAPED_UNICODE),json_encode($new,JSON_UNESCAPED_UNICODE)]);flash('عملیات با موفقیت انجام شد.');}catch(Throwable $e){error_log('Assessment recalculate: '.$e->getMessage());flash('خطا در ذخیره‌سازی اطلاعات. لطفاً مجدد تلاش کنید.','danger');}redirect('/admin/hr-assessment-results.php');}
$where=['r.employee_id IN ('.implode(',',array_fill(0,count($ids),'?')).')'];$params=$ids;foreach(['employee_id'=>'r.employee_id','test_id'=>'r.test_id'] as $key=>$col){$v=(int)($_GET[$key]??0);if($v){$where[]="$col=?";$params[]=$v;}}foreach(['department'=>'u.department','role_key'=>'u.role_key','sales_line'=>'u.sales_line','risk_level'=>'r.risk_level','period_key'=>'a.period_key'] as $key=>$col){$v=trim($_GET[$key]??'');if($v!==''){$where[]="$col=?";$params[]=$v;}}if(trim($_GET['from_date']??'')!==''){$where[]='DATE(r.calculated_at)>=?';$params[]=JalaliDate::toGregorian($_GET['from_date'])?:$_GET['from_date'];}if(trim($_GET['to_date']??'')!==''){$where[]='DATE(r.calculated_at)<=?';$params[]=JalaliDate::toGregorian($_GET['to_date'])?:$_GET['to_date'];}
foreach(['org_unit_id'=>'u.org_unit_id','org_role_id'=>'u.org_role_id','supervisor_id'=>'a.supervisor_id','manager_id'=>'a.manager_id'] as $key=>$col){$v=(int)($_GET[$key]??0);if($v){$where[]="$col=?";$params[]=$v;}}if(trim((string)($_GET['status']??''))!==''){$where[]='a.status=?';$params[]=trim((string)$_GET['status']);}if((int)($_GET['assignment_id']??0)>0){$where[]='a.id=?';$params[]=(int)$_GET['assignment_id'];}
$sql='SELECT r.*,u.name employee_name,COALESCE(ou.title,u.department) department,COALESCE(orr.code,u.role_key) role_key,u.sales_line,t.title test_title,t.code test_code,t.category,a.period_key,a.due_date,a.status assignment_status,sup.name supervisor_name,mgr.name manager_name FROM hr_assessment_results r JOIN users u ON u.id=r.employee_id JOIN hr_assessment_tests t ON t.id=r.test_id JOIN hr_assessment_assignments a ON a.id=r.assignment_id LEFT JOIN org_units ou ON ou.id=u.org_unit_id LEFT JOIN org_roles orr ON orr.id=u.org_role_id LEFT JOIN users sup ON sup.id=a.supervisor_id LEFT JOIN users mgr ON mgr.id=a.manager_id WHERE '.implode(' AND ',$where).' ORDER BY r.id DESC';try{$results=Database::fetchAll($sql,$params);}catch(Throwable $e){error_log('HR assessment results query: '.$e->getMessage());$results=[];flash('دریافت نتایج ارزیابی در حال حاضر ممکن نیست.','danger');}
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="hr-assessment-results.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['نام','واحد','نقش','لاین','آزمون','کد','نتیجه','ریسک','امتیازها','تاریخ']);foreach($results as $r)fputcsv($out,[$r['employee_name'],$r['department'],$r['role_key'],$r['sales_line'],$r['test_title'],$r['test_code'],$r['final_result'],$r['risk_level'],$r['normalized_scores_json'],$r['calculated_at']]);fclose($out);exit;}
$employees=Database::fetchAll('SELECT id,name FROM users WHERE id IN ('.implode(',',array_fill(0,count($ids),'?')).') ORDER BY name',$ids);$tests=Database::fetchAll('SELECT id,title FROM hr_assessment_tests ORDER BY title');$units=Database::fetchAll('SELECT id,title FROM org_units WHERE active=1 ORDER BY sort_order,title');$roles=Database::fetchAll('SELECT id,title FROM org_roles WHERE active=1 ORDER BY sort_order,title');$leaders=Database::fetchAll('SELECT id,name FROM users WHERE status="active" AND id IN ('.implode(',',array_fill(0,count($ids),'?')).') ORDER BY name',$ids);
$satisfactionValues=[];foreach($results as $row){if($row['test_code']!=='JOB_SATISFACTION')continue;$scores=json_decode($row['normalized_scores_json']?:'{}',true);if(is_array($scores)&&$scores){$satisfactionValues[]=array_sum($scores)/count($scores);}}$avgSatisfaction=$satisfactionValues?array_sum($satisfactionValues)/count($satisfactionValues):0.0;
$followups=count(array_filter($results,fn($r)=>$r['risk_level']==='نیازمند پیگیری'));require __DIR__.'/../views/partials/admin-header.php';?>
<div class="stats"><div class="stat-card"><span>نتایج قابل مشاهده</span><strong><?=count($results)?></strong></div><div class="stat-card"><span>میانگین رضایت</span><strong><?=e(number_format($avgSatisfaction,1))?>٪</strong></div><div class="stat-card"><span>نیازمند پیگیری HR</span><strong><?=$followups?></strong></div></div>
<form class="card admin-form" method="get"><h2>فیلتر نتایج</h2><div class="grid grid-3"><label class="form-field"><span>کارمند</span><select name="employee_id"><option value="">همه</option><?php foreach($employees as $e):?><option value="<?=$e['id']?>"><?=e($e['name'])?></option><?php endforeach?></select></label><label class="form-field"><span>آزمون</span><select name="test_id"><option value="">همه</option><?php foreach($tests as $t):?><option value="<?=$t['id']?>"><?=e($t['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>واحد</span><input name="department" value="<?=e($_GET['department']??'')?>"></label><label class="form-field"><span>نقش</span><input name="role_key" value="<?=e($_GET['role_key']??'')?>"></label><label class="form-field"><span>لاین</span><input name="sales_line" value="<?=e($_GET['sales_line']??'')?>"></label><label class="form-field"><span>سطح پیگیری</span><input name="risk_level" value="<?=e($_GET['risk_level']??'')?>"></label><label class="form-field"><span>دوره</span><input name="period_key" value="<?=e($_GET['period_key']??'')?>"></label><label class="form-field"><span>از تاریخ</span><input class="jalali-date-input" name="from_date"></label><label class="form-field"><span>تا تاریخ</span><input class="jalali-date-input" name="to_date"></label></div><div class="form-actions"><button class="btn btn-primary">اعمال فیلتر</button><button class="btn" name="export" value="csv">خروجی CSV</button></div></form>
<section class="card"><div class="table-wrap"><table><thead><tr><th>کارمند</th><th>واحد / نقش</th><th>آزمون</th><th>نتیجه</th><th>سطح پیگیری</th><th>تاریخ</th><th>عملیات</th></tr></thead><tbody><?php foreach($results as $r):$scores=json_decode($r['normalized_scores_json'],true)?:[];?><tr><td><?=e($r['employee_name'])?></td><td><?=e(($r['department']?:'-').' / '.($r['role_key']?:'-'))?></td><td><?=e($r['test_title'])?></td><td><?=e($r['final_result'])?></td><td><span class="badge"><?=e($r['risk_level'])?></span></td><td><?=e(format_jalali_datetime($r['calculated_at']))?></td><td><details><summary>مشاهده تفکیک</summary><p><?=e($r['profile_summary'])?></p><ul><?php foreach($scores as $key=>$score):?><li><?=e($key)?>: <?=e($score)?>٪</li><?php endforeach?></ul><p><?=e($r['recommendation_text'])?></p><button class="btn btn-small" onclick="window.print()">چاپ</button><?php if(Auth::isAdmin()||Auth::can('hr_assessments.recalculate')):?><form method="post" onsubmit="return confirm('محاسبه مجدد انجام شود؟')"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="result_id" value="<?=$r['id']?>"><button class="btn btn-small">محاسبه مجدد</button></form><?php endif?></details></td></tr><?php endforeach?><?php if(!$results):?><tr><td colspan="7">نتیجه‌ای یافت نشد.</td></tr><?php endif?></tbody></table></div></section>
<form class="card admin-form" method="get"><h2>فیلتر سازمانی نتایج</h2><div class="grid grid-3"><label class="form-field"><span>واحد</span><select name="org_unit_id"><option value="">همه</option><?php foreach($units as $item):?><option value="<?=$item['id']?>" <?=(int)($_GET['org_unit_id']??0)===(int)$item['id']?'selected':''?>><?=e($item['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>نقش</span><select name="org_role_id"><option value="">همه</option><?php foreach($roles as $item):?><option value="<?=$item['id']?>" <?=(int)($_GET['org_role_id']??0)===(int)$item['id']?'selected':''?>><?=e($item['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>سرپرست</span><select name="supervisor_id"><option value="">همه</option><?php foreach($leaders as $item):?><option value="<?=$item['id']?>" <?=(int)($_GET['supervisor_id']??0)===(int)$item['id']?'selected':''?>><?=e($item['name'])?></option><?php endforeach?></select></label><label class="form-field"><span>مدیر</span><select name="manager_id"><option value="">همه</option><?php foreach($leaders as $item):?><option value="<?=$item['id']?>" <?=(int)($_GET['manager_id']??0)===(int)$item['id']?'selected':''?>><?=e($item['name'])?></option><?php endforeach?></select></label><label class="form-field"><span>وضعیت تخصیص</span><select name="status"><option value="">همه</option><?php foreach(['assigned'=>'تخصیص‌شده','in_progress'=>'در حال انجام','submitted'=>'ثبت نهایی','cancelled'=>'لغوشده'] as $value=>$label):?><option value="<?=$value?>" <?=($_GET['status']??'')===$value?'selected':''?>><?=$label?></option><?php endforeach?></select></label></div><div class="form-actions"><button class="btn btn-primary">اعمال فیلتر سازمانی</button><a class="btn" href="/admin/hr-assessment-results.php">پاکسازی</a></div></form>
</section></main></div><script src="/assets/js/app.js"></script></body></html>
